CREATE TABLE users (
 id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE,
 phone VARCHAR(20) UNIQUE, password_hash VARCHAR(100) NOT NULL,
 role ENUM('candidate','admin','invigilator','examiner') NOT NULL DEFAULT 'candidate',
 status ENUM('pending','active','disabled') NOT NULL DEFAULT 'pending',
 email_verified_at DATETIME(3), phone_verified_at DATETIME(3), center_id CHAR(36),
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
);
CREATE TABLE students (user_id CHAR(36) PRIMARY KEY, dob DATE NOT NULL, address VARCHAR(500) NOT NULL, selected_exam_id CHAR(36), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE sessions (token_hash CHAR(64) PRIMARY KEY, user_id CHAR(36) NOT NULL, expires_at DATETIME(3) NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(user_id) REFERENCES users(id), INDEX(expires_at), INDEX(user_id));
CREATE TABLE contact_verifications (user_id CHAR(36) NOT NULL, purpose ENUM('email','sms','recovery') NOT NULL, code_hash CHAR(64), provider_sid VARCHAR(40), expires_at DATETIME(3) NOT NULL, sent_at DATETIME(3) NOT NULL, attempts INT NOT NULL DEFAULT 0, consumed_at DATETIME(3), PRIMARY KEY(user_id,purpose), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE rate_limits (bucket_key CHAR(64) PRIMARY KEY, hits INT NOT NULL, resets_at DATETIME(3) NOT NULL, INDEX(resets_at));
CREATE TABLE exam_centers (id CHAR(36) PRIMARY KEY, name VARCHAR(150) NOT NULL, address VARCHAR(500) NOT NULL, city VARCHAR(100) NOT NULL, state VARCHAR(100) NOT NULL, capacity INT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, CHECK(capacity>0));
ALTER TABLE users ADD FOREIGN KEY(center_id) REFERENCES exam_centers(id);
CREATE TABLE computers (id CHAR(36) PRIMARY KEY, center_id CHAR(36) NOT NULL, label VARCHAR(50) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(center_id,label), FOREIGN KEY(center_id) REFERENCES exam_centers(id));
CREATE TABLE examinations (id CHAR(36) PRIMARY KEY, name VARCHAR(150) NOT NULL, description TEXT NOT NULL, instructions TEXT NOT NULL, duration_minutes INT NOT NULL, registration_start DATETIME(3) NOT NULL, registration_end DATETIME(3) NOT NULL, fee DECIMAL(10,2) NOT NULL DEFAULT 0, status ENUM('draft','open','closed','active','completed') NOT NULL DEFAULT 'draft', created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), CHECK(duration_minutes>0), CHECK(registration_end>registration_start));
ALTER TABLE students ADD FOREIGN KEY(selected_exam_id) REFERENCES examinations(id);
CREATE TABLE registrations (id CHAR(36) PRIMARY KEY, registration_number VARCHAR(45) NOT NULL UNIQUE, application_number VARCHAR(45) NOT NULL UNIQUE, user_id CHAR(36) NOT NULL, exam_id CHAR(36) NOT NULL, status ENUM('payment_pending','completed','cancelled') NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE(user_id,exam_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(exam_id) REFERENCES examinations(id));
CREATE TABLE payments (id CHAR(36) PRIMARY KEY, registration_id CHAR(36) NOT NULL UNIQUE, user_id CHAR(36) NOT NULL, amount DECIMAL(10,2) NOT NULL, status ENUM('Pending','Successful','Failed') NOT NULL DEFAULT 'Pending', mode ENUM('simulation') NOT NULL DEFAULT 'simulation', paid_at DATETIME(3), FOREIGN KEY(registration_id) REFERENCES registrations(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE exam_slots (id CHAR(36) PRIMARY KEY, exam_id CHAR(36) NOT NULL, center_id CHAR(36) NOT NULL, starts_at DATETIME(3) NOT NULL, ends_at DATETIME(3) NOT NULL, capacity INT NOT NULL, FOREIGN KEY(exam_id) REFERENCES examinations(id), FOREIGN KEY(center_id) REFERENCES exam_centers(id), INDEX(center_id,starts_at,ends_at), CHECK(ends_at>starts_at), CHECK(capacity>0));
CREATE TABLE candidate_allocations (id CHAR(36) PRIMARY KEY, registration_id CHAR(36) NOT NULL UNIQUE, slot_id CHAR(36) NOT NULL, attendance ENUM('Not Arrived','Present','Verified','Absent','Exam Started','Exam Submitted') NOT NULL DEFAULT 'Not Arrived', verified_by CHAR(36), verified_at DATETIME(3), computer_id CHAR(36), UNIQUE(slot_id,computer_id), FOREIGN KEY(registration_id) REFERENCES registrations(id), FOREIGN KEY(slot_id) REFERENCES exam_slots(id), FOREIGN KEY(verified_by) REFERENCES users(id), FOREIGN KEY(computer_id) REFERENCES computers(id));
CREATE TABLE hall_tickets (allocation_id CHAR(36) PRIMARY KEY, hall_number VARCHAR(45) NOT NULL UNIQUE, exam_password_hash VARCHAR(100), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(allocation_id) REFERENCES candidate_allocations(id));
CREATE TABLE activation_tokens (token_hash CHAR(64) PRIMARY KEY, allocation_id CHAR(36) NOT NULL, expires_at DATETIME(3) NOT NULL, consumed_at DATETIME(3), FOREIGN KEY(allocation_id) REFERENCES candidate_allocations(id));
CREATE TABLE workstation_sessions (token_hash CHAR(64) PRIMARY KEY, computer_id CHAR(36) NOT NULL, slot_id CHAR(36) NOT NULL, expires_at DATETIME(3) NOT NULL, issued_by CHAR(36) NOT NULL, FOREIGN KEY(computer_id) REFERENCES computers(id), FOREIGN KEY(slot_id) REFERENCES exam_slots(id), FOREIGN KEY(issued_by) REFERENCES users(id), INDEX(expires_at));
CREATE TABLE questions (id CHAR(36) PRIMARY KEY, exam_id CHAR(36) NOT NULL, type ENUM('MCQ','MSQ','NAT') NOT NULL, prompt TEXT NOT NULL, marks DECIMAL(6,2) NOT NULL, negative_marks DECIMAL(6,2) NOT NULL DEFAULT 0, position INT NOT NULL, UNIQUE(exam_id,position), FOREIGN KEY(exam_id) REFERENCES examinations(id));
CREATE TABLE question_options (question_id CHAR(36) NOT NULL, option_id CHAR(1) NOT NULL, option_text TEXT NOT NULL, PRIMARY KEY(question_id,option_id), FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE);
CREATE TABLE answer_keys (question_id CHAR(36) PRIMARY KEY, correct_answer JSON NOT NULL, tolerance DECIMAL(8,4) NOT NULL DEFAULT 0, FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE);
CREATE TABLE exam_attempts (id CHAR(36) PRIMARY KEY, allocation_id CHAR(36) NOT NULL UNIQUE, access_hash CHAR(64) NOT NULL UNIQUE, started_at DATETIME(3) NOT NULL, deadline DATETIME(3) NOT NULL, submitted_at DATETIME(3), status ENUM('in_progress','submitted') NOT NULL DEFAULT 'in_progress', FOREIGN KEY(allocation_id) REFERENCES candidate_allocations(id), INDEX(status,deadline));
CREATE TABLE student_answers (attempt_id CHAR(36) NOT NULL, question_id CHAR(36) NOT NULL, answer JSON, visited BOOLEAN NOT NULL DEFAULT TRUE, review BOOLEAN NOT NULL DEFAULT FALSE, revision INT NOT NULL DEFAULT 1, updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY(attempt_id,question_id), FOREIGN KEY(attempt_id) REFERENCES exam_attempts(id), FOREIGN KEY(question_id) REFERENCES questions(id));
CREATE TABLE results (attempt_id CHAR(36) PRIMARY KEY, score DECIMAL(9,2), status ENUM('Not Evaluated','Evaluated','Published') NOT NULL DEFAULT 'Not Evaluated', evaluated_at DATETIME(3), published_at DATETIME(3), FOREIGN KEY(attempt_id) REFERENCES exam_attempts(id));
CREATE TABLE notifications (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, event VARCHAR(80) NOT NULL, payload_encrypted MEDIUMTEXT, status ENUM('pending','sending','sent','failed') NOT NULL DEFAULT 'pending', attempts INT NOT NULL DEFAULT 0, available_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), sent_at DATETIME(3), error_code VARCHAR(80), FOREIGN KEY(user_id) REFERENCES users(id), INDEX(status,available_at));
CREATE TABLE audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_id CHAR(36), action VARCHAR(100) NOT NULL, entity_id VARCHAR(50), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(actor_id) REFERENCES users(id), INDEX(created_at));
